deliverable.manifest:
{
  "manifest_version": 3,
  "name": "Full Page PNG Capture",
  "version": "1.0.0",
  "description": "Capture a full webpage into a single PNG via scrolling and stitching.",
  "permissions": [
    "activeTab",
    "scripting",
    "tabs",
    "downloads",
    "storage"
  ],
  "host_permissions": ["<all_urls>"],
  "background": {
    "service_worker": "background.js"
  },
  "action": {
    "default_title": "Capture full page",
    "default_popup": "popup.html"
  },
  "content_scripts": [
    {
      "matches": ["<all_urls>"],
      "js": ["content.js"],
      "run_at": "document_idle"
    }
  ]
}

deliverable.background_script:
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "CAPTURE_VISIBLE_TAB") {
    const { windowId } = message;
    chrome.tabs.captureVisibleTab(
      windowId,
      { format: "png" },
      (dataUrl) => {
        if (chrome.runtime.lastError) {
          sendResponse({ ok: false, error: chrome.runtime.lastError.message });
          return;
        }
        sendResponse({ ok: true, dataUrl });
      }
    );
    return true;
  }

  if (message?.type === "DOWNLOAD_PNG") {
    const { dataUrl, filename } = message;
    chrome.downloads.download(
      {
        url: dataUrl,
        filename,
        saveAs: true
      },
      (downloadId) => {
        if (chrome.runtime.lastError) {
          sendResponse({ ok: false, error: chrome.runtime.lastError.message });
          return;
        }
        sendResponse({ ok: true, downloadId });
      }
    );
    return true;
  }

  return false;
});

deliverable.content_script:
let hiddenElements = [];

const getScrollableHeight = () =>
  Math.max(
    document.body.scrollHeight,
    document.documentElement.scrollHeight,
    document.body.offsetHeight,
    document.documentElement.offsetHeight,
    document.body.clientHeight,
    document.documentElement.clientHeight
  );

const getViewportSize = () => ({
  width: window.innerWidth,
  height: window.innerHeight
});

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const scrollToBottomUntilStable = async ({ step, delay, settleRounds, maxRounds }) => {
  let stableRounds = 0;
  let previousHeight = 0;
  let rounds = 0;

  while (stableRounds < settleRounds && rounds < maxRounds) {
    const totalHeight = getScrollableHeight();
    const viewportHeight = getViewportSize().height;
    const maxScrollY = Math.max(0, totalHeight - viewportHeight);
    const currentY = Math.min(window.scrollY + step, maxScrollY);

    window.scrollTo(0, currentY);
    await sleep(delay);

    const newHeight = getScrollableHeight();
    if (currentY >= maxScrollY && newHeight === previousHeight) {
      stableRounds += 1;
    } else {
      stableRounds = 0;
    }

    previousHeight = newHeight;
    rounds += 1;
  }

  return { totalHeight: getScrollableHeight(), stableRounds, rounds };
};

const hideFixedAndSticky = () => {
  hiddenElements = [];
  const elements = Array.from(document.querySelectorAll("*"));
  for (const el of elements) {
    const style = window.getComputedStyle(el);
    if (style.position === "fixed" || style.position === "sticky") {
      const previousVisibility = el.style.visibility;
      el.style.visibility = "hidden";
      hiddenElements.push({ el, previousVisibility });
    }
  }
};

const restoreFixedAndSticky = () => {
  for (const { el, previousVisibility } of hiddenElements) {
    el.style.visibility = previousVisibility;
  }
  hiddenElements = [];
};

const warmUpLazyLoad = async (step, delay) => {
  const totalHeight = getScrollableHeight();
  const viewportHeight = getViewportSize().height;
  const maxScrollY = totalHeight - viewportHeight;
  let currentY = 0;

  while (currentY < maxScrollY) {
    window.scrollTo(0, currentY);
    await sleep(delay);
    currentY += step;
  }

  window.scrollTo(0, maxScrollY);
  await sleep(delay);
  window.scrollTo(0, 0);
  await sleep(delay);
};

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_PAGE_METRICS") {
    sendResponse({
      totalHeight: getScrollableHeight(),
      viewport: getViewportSize(),
      devicePixelRatio: window.devicePixelRatio
    });
    return true;
  }

  if (message?.type === "SCROLL_TO") {
    window.scrollTo(0, message.scrollY || 0);
    sendResponse({ ok: true });
    return true;
  }

  if (message?.type === "HIDE_FIXED") {
    hideFixedAndSticky();
    sendResponse({ ok: true });
    return true;
  }

  if (message?.type === "RESTORE_FIXED") {
    restoreFixedAndSticky();
    sendResponse({ ok: true });
    return true;
  }

  if (message?.type === "WARMUP_LAZY") {
    warmUpLazyLoad(message.step, message.delay)
      .then(() => sendResponse({ ok: true }))
      .catch((error) => sendResponse({ ok: false, error: error.message }));
    return true;
  }

  if (message?.type === "AUTO_EXPAND") {
    scrollToBottomUntilStable(message.options)
      .then((result) => sendResponse({ ok: true, result }))
      .catch((error) => sendResponse({ ok: false, error: error.message }));
    return true;
  }

  return false;
});

deliverable.popup_js:
const statusEl = document.getElementById("status");
const captureButton = document.getElementById("capture");
const hideFixedCheckbox = document.getElementById("hideFixed");
const warmupCheckbox = document.getElementById("warmupLazy");
const autoExpandCheckbox = document.getElementById("autoExpand");

const CONFIG = {
  scrollDelayMs: 300,
  warmupDelayMs: 350,
  warmupStepPx: 600,
  tileOverlapPx: 0,
  maxCanvasHeightPx: 32767,
  autoExpandStepPx: 800,
  autoExpandDelayMs: 400,
  autoExpandSettleRounds: 3,
  autoExpandMaxRounds: 80
};

const setStatus = (message) => {
  statusEl.textContent = message;
};

const getActiveTab = async () => {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  if (!tab) {
    throw new Error("No active tab found.");
  }
  return tab;
};

const sendToContent = (tabId, message) =>
  chrome.tabs.sendMessage(tabId, message);

const captureVisible = async (windowId) => {
  const response = await chrome.runtime.sendMessage({
    type: "CAPTURE_VISIBLE_TAB",
    windowId
  });
  if (!response?.ok) {
    throw new Error(response?.error || "Failed to capture visible tab.");
  }
  return response.dataUrl;
};

const downloadPng = async (dataUrl, filename) => {
  const response = await chrome.runtime.sendMessage({
    type: "DOWNLOAD_PNG",
    dataUrl,
    filename
  });
  if (!response?.ok) {
    throw new Error(response?.error || "Failed to save PNG.");
  }
  return response.downloadId;
};

const dataUrlToBitmap = async (dataUrl) => {
  const response = await fetch(dataUrl);
  const blob = await response.blob();
  return createImageBitmap(blob);
};

const autoExpandContent = async (tabId) => {
  const response = await sendToContent(tabId, {
    type: "AUTO_EXPAND",
    options: {
      step: CONFIG.autoExpandStepPx,
      delay: CONFIG.autoExpandDelayMs,
      settleRounds: CONFIG.autoExpandSettleRounds,
      maxRounds: CONFIG.autoExpandMaxRounds
    }
  });

  if (!response?.ok) {
    throw new Error(response?.error || "Failed to auto-expand content.");
  }

  return response.result;
};

const createCanvas = (width, height) => {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  return canvas;
};

const drawTile = (parts, image, tileTopPx, tileHeightPx, partHeightPx) => {
  const tileBottomPx = tileTopPx + tileHeightPx;
  let remainingTop = tileTopPx;
  let remainingHeight = tileHeightPx;

  while (remainingHeight > 0) {
    const partIndex = Math.floor(remainingTop / partHeightPx);
    const part = parts[partIndex];
    const partTopPx = partIndex * partHeightPx;
    const drawTopPx = remainingTop - partTopPx;
    const availableHeight = Math.min(
      partHeightPx - drawTopPx,
      remainingHeight
    );

    const sourceOffset = tileHeightPx - remainingHeight;
    part.ctx.drawImage(
      image,
      0,
      sourceOffset,
      image.width,
      availableHeight,
      0,
      drawTopPx,
      image.width,
      availableHeight
    );

    remainingTop += availableHeight;
    remainingHeight -= availableHeight;
  }
};

const runCapture = async () => {
  captureButton.disabled = true;
  setStatus("Starting capture…");

  const tab = await getActiveTab();
  const tabId = tab.id;

  if (hideFixedCheckbox.checked) {
    await sendToContent(tabId, { type: "HIDE_FIXED" });
  }

  if (warmupCheckbox.checked) {
    setStatus("Warming up lazy-loaded content…");
    await sendToContent(tabId, {
      type: "WARMUP_LAZY",
      step: CONFIG.warmupStepPx,
      delay: CONFIG.warmupDelayMs
    });
  }

  if (autoExpandCheckbox.checked) {
    setStatus("Auto-scrolling to load extra content…");
    await autoExpandContent(tabId);
  }

  const metrics = await sendToContent(tabId, { type: "GET_PAGE_METRICS" });
  const { totalHeight, viewport, devicePixelRatio } = metrics;
  const dpr = devicePixelRatio || 1;
  const viewportHeight = viewport.height;
  const viewportWidth = viewport.width;

  const totalHeightPx = Math.ceil(totalHeight * dpr);
  const totalWidthPx = Math.ceil(viewportWidth * dpr);
  const partHeightPx = Math.min(CONFIG.maxCanvasHeightPx, totalHeightPx);
  const partCount = Math.ceil(totalHeightPx / partHeightPx);

  const parts = Array.from({ length: partCount }, (_, index) => {
    const height =
      index === partCount - 1
        ? totalHeightPx - index * partHeightPx
        : partHeightPx;
    const canvas = createCanvas(totalWidthPx, height);
    return { canvas, ctx: canvas.getContext("2d") };
  });

  const scrollStep = viewportHeight - CONFIG.tileOverlapPx;
  const maxScrollY = Math.max(0, totalHeight - viewportHeight);
  let scrollY = 0;
  let tileIndex = 0;

  while (scrollY <= maxScrollY) {
    setStatus(`Capturing section ${tileIndex + 1}…`);
    await sendToContent(tabId, { type: "SCROLL_TO", scrollY });
    await new Promise((resolve) => setTimeout(resolve, CONFIG.scrollDelayMs));

    const dataUrl = await captureVisible(tab.windowId);
    const bitmap = await dataUrlToBitmap(dataUrl);

    const tileTopPx = Math.floor(scrollY * dpr);
    const tileHeightPx = bitmap.height;
    drawTile(parts, bitmap, tileTopPx, tileHeightPx, partHeightPx);

    scrollY += scrollStep;
    tileIndex += 1;

    if (scrollY > maxScrollY && scrollY - scrollStep < maxScrollY) {
      scrollY = maxScrollY;
    }
  }

  await sendToContent(tabId, { type: "SCROLL_TO", scrollY: 0 });

  if (hideFixedCheckbox.checked) {
    await sendToContent(tabId, { type: "RESTORE_FIXED" });
  }

  const now = new Date();
  const timestamp = now
    .toISOString()
    .replace(/[:.]/g, "-")
    .replace("T", "_")
    .replace("Z", "");

  for (let i = 0; i < parts.length; i += 1) {
    setStatus(`Saving PNG ${i + 1} of ${parts.length}…`);
    const filename =
      parts.length === 1
        ? `full-page-${timestamp}.png`
        : `full-page-${timestamp}-part-${i + 1}.png`;
    const dataUrl = parts[i].canvas.toDataURL("image/png");
    await downloadPng(dataUrl, filename);
  }

  setStatus("Capture complete.");
  captureButton.disabled = false;
};

captureButton.addEventListener("click", () => {
  runCapture().catch((error) => {
    console.error(error);
    setStatus(`Error: ${error.message}`);
    captureButton.disabled = false;
  });
});

deliverable.popup_css:
:root {
  color-scheme: light dark;
  font-family: "Segoe UI", system-ui, sans-serif;
}

body {
  margin: 0;
  padding: 16px;
  width: 260px;
}

h1 {
  font-size: 16px;
  margin: 0 0 12px;
}

.option {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 13px;
  margin-bottom: 8px;
}

button {
  width: 100%;
  padding: 8px 12px;
  border: none;
  border-radius: 6px;
  background: #2d6cdf;
  color: #fff;
  font-size: 14px;
  cursor: pointer;
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

#status {
  min-height: 18px;
  font-size: 12px;
  margin-top: 10px;
}
